See https://github.com/LLK/scratch-paint/issues/13 */

$ui-pane-border: #D9D9D9;
$ui-pane-gray: #F9F9F9;
$ui-background-blue: #e8edf1;

$text-primary: #575e75;

$looks-secondary: #855CD6;
$looks-transparent: hsla(260, 60%, 60%, 0.35); /* 35% transparent version of looks-secondary */

$red-primary: #FF661A;
$red-tertiary: #E64D00;

$sound-primary: #CF63CF;
$sound-tertiary: #A63FA6;

$control-primary: #FFAB19;

$data-primary: #FF8C1A;

$form-border: #E9EEF2;
/* DO NOT EDIT
@todo This file is copied from GUI and should be pulled out into a shared library.
See https://github.com/LLK/scratch-paint/issues/13 */

/* ACTUALLY, THIS IS EDITED ;)
THIS WAS CHANGED ON 10/25/2017 BY @mewtaylor TO ADD A VARIABLE FOR THE SMALLEST
GRID UNITS.

ALSO EDITED ON 11/13/2017 TO ADD IN CONTANTS FOR LAYOUT FROM `layout-contents.js`*/

$space: 0.5rem;
$grid-unit: .25rem;

$sprites-per-row: 5;

$menu-bar-height: 3rem;
$sprite-info-height: 6rem;
$stage-menu-height: 2.75rem;

$library-header-height: 4.375rem;

$form-radius: calc($space / 2);

/* layout contants from `layout-constants.js`, minus 1px */
$full-size: 1095px;
$full-size-paint: 1256px;
@import "../../css/colors";
@import "../../css/units";

/* Popover styles */
:global(.Popover-body) {
    background: white;
    border: 1px solid #ddd;
    padding: 4px;
    border-radius: 4px;
    padding: 4px;
    box-shadow: 0px 0px 8px 1px rgba(0, 0, 0, .3);
}

:global(.Popover-tipShape) {
    fill: white;
    stroke: #ddd;
}

.clickable {
    cursor: pointer;
}

.swatch-row {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
}

.row-header {
    font-family: "Helvetica Neue", Helvetica, sans-serif;
    font-size: 0.65rem;
    color: #575E75;
    margin: 8px;
}

[dir="ltr"] .label-readout {
    margin-left: 10px;
}

[dir="rtl"] .label-readout {
    margin-right: 10px;
}

.label-name {
    font-weight: bold;
}

.divider {
    border-top: 1px solid #ddd;
    margin: 8px;
}

.swap-button {
    margin-left: 8px;
    margin-right: 8px;
}

.swatches {
    margin: 8px;
}

.swatch {
    width: 1.5rem;
    height: 1.5rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    box-sizing: content-box;
    display: flex;
    align-items: center;
}

.large-swatch-icon {
    width: 1.75rem;
    margin: auto;
}

.large-swatch {
    width: 2rem;
    height: 2rem;
}

.active-swatch {
    border: 1px solid $looks-secondary;
    box-shadow: 0px 0px 0px 3px $looks-transparent;
}

.swatch-icon {
    width: 1.5rem;
    height: 1.5rem;
}

.inactive-gradient {
    filter: saturate(0%);
}

.gradient-picker-row {
    align-items: center;
    display: flex;
    flex-direction: row;
    justify-content: center;
    margin: 8px;
    user-select: none;
}

[dir="ltr"] .gradient-picker-row > img + img {
    margin-left: calc(2 * $grid-unit);
}

[dir="rtl"] .gradient-picker-row > img + img {
    margin-right: calc(2 * $grid-unit);
}

[dir="rtl"] .gradient-swatches-row {
    flex-direction: row-reverse;
}
